            int heldReviewedBound=StrategicHpRecoveryBound.ComponentHealingUpperBound(parent,player,0,useReviewedSources:true);
            if(heldKnownBound!=int.MaxValue||heldReviewedBound!=int.MaxValue)
                throw new InvalidOperationException("Existing legal Fruit Juice must remain uncertified.");
