            GameAction action=await SolverController.EnqueueAndCaptureActionAsync(
                candidate=>candidate is UsePotionAction use&&ReferenceEquals(use.Player,player)&&use.PotionIndex==0,
                ()=>juice.EnqueueManualUse(player.Creature),deadline.Token);
            await action.CompletionTask.WaitAsync(deadline.Token);
            var predicted=child.State.GetCreature(player.Creature);
            int requested=checked((int)decimal.Ceiling(shadow.DynamicVars.MaxHp.BaseValue));
            int optimistic=new TaskRecoveryCapacityEnvelope(requested,requested).OptimisticRecovered(0,75,75)!.Value;
            int actualRecovered=player.Creature.CurrentHp-75;
            if(predicted.MaxHp!=80||predicted.CurrentHp!=80||player.Creature.MaxHp!=83||player.Creature.CurrentHp!=83
                ||callbacks!=2||actualRecovered<=optimistic||DescribeContinuationContractState(parent,root,player)!=parentBefore)
                throw new InvalidOperationException("Unknown maximum observer counterexample did not reproduce.");
            var output=new{requested,optimistic,actualRecovered,callbacks,predictedHp=predicted.CurrentHp,predictedMaxHp=predicted.MaxHp,
                nativeHp=player.Creature.CurrentHp,nativeMaxHp=player.Creature.MaxHp,knownPolicyBound=heldKnownBound,
                reviewedComponentBound=heldReviewedBound,shadowDidNotInvokeLiveObserver=true,frozenParentAfterNativeAdvance=true,
                wholeSourceCertificate=false,productionPrunes=0,searchStarted=false};
            File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/finite-health-capacity-proof-20261008/unknown-audience-details.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
            _completedChecks.Add("TaskCapacity:UnknownMaxHpEvent:RequestedFiveActualEight:ExistingFruitRefusal:ParentIsolation");
            _completedChecks.Add("TASK_CAPACITY_UNKNOWN_AUDIENCE "+JsonSerializer.Serialize(output));
