    private void AssertTaskHealthAudienceInventory(CombatState live)
    {
        SetStage("task_health_audience_inventory");
        object Describe(Delegate callback)
        {
            MethodInfo method=callback.Method;
            Patches? patches=Harmony.GetPatchInfo(method);
            var tracker=method.DeclaringType?.FullName=="MegaCrit.Sts2.Core.Combat.CombatStateTracker"
                ? method.DeclaringType.GetField("CombatStateChanged",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.DeclaredOnly)?.GetValue(callback.Target) as Delegate:null;
            return new{method.DeclaringType?.FullName,method.Name,method.IsStatic,method.MetadataToken,
                assembly=method.Module.Assembly.GetName().Name,mvid=method.Module.ModuleVersionId,
                targetType=callback.Target?.GetType().FullName,
                ilSha256=Convert.ToHexString(SHA256.HashData(method.GetMethodBody()?.GetILAsByteArray()??Array.Empty<byte>())),
                patches=patches?.Prefixes.Concat(patches.Postfixes).Concat(patches.Transpilers).Concat(patches.Finalizers)
                    .Select(patch=>new{patch.owner,method=patch.PatchMethod.ToString(),declaringType=patch.PatchMethod.DeclaringType?.FullName}).ToArray(),
                nestedTrackerAudience=tracker?.GetInvocationList().Select(Describe).ToArray()};
        }
        var rows=new List<object>();
        foreach(var creature in live.Creatures)
            foreach(string eventName in new[]{"CurrentHpChanged","MaxHpChanged"})
            {
                FieldInfo field=typeof(Creature).GetField(eventName,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.DeclaredOnly)
                    ??throw new InvalidOperationException("Native health event backing field absent.");
                var handlers=field.GetValue(creature) as Delegate;
                rows.Add(new{creature.CombatId,isPlayer=creature.IsPlayer,eventName,
                    handlers=handlers?.GetInvocationList().Select(Describe).ToArray()??Array.Empty<object>()});
            }
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/finite-health-capacity-proof-20261008/health-audience-inventory.json",JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));
        _completedChecks.Add("TaskHealthAudience:ActualCreatureAndTrackerDelegates:PatchAndIlIdentity:ReadOnly");
    }

    private async Task AssertTaskDeferredHealthAudienceAsync(CombatState live, Player player)
    {
