        await CreatureCmd.SetCurrentHp(player.Creature,60);
        foreach(var potion in player.PotionSlots.ToArray()) potion?.Discard();
        // Flush notifications created by setup before adding our own subscriber.
        for(int i=0;i<3;i++) await NGame.Instance.ToSignal(NGame.Instance.GetTree(),Godot.SceneTree.SignalName.ProcessFrame);
        bool armed=false, healed=false; int callbacks=0;
        void UnknownDeferredObserver(CombatState state)
        {
            if(!armed || !ReferenceEquals(state,live))return;
            callbacks++;
            if(!healed && player.Creature.CurrentHp<60)
            {
                healed=true;
                player.Creature.HealInternal(2);
            }
        }
        CombatManager.Instance.StateTracker.CombatStateChanged+=UnknownDeferredObserver;
        try
        {
            var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();var child=parent.Fork();
            string parentBefore=DescribeContinuationContractState(parent,root,player);
            string liveBefore=ContinuationStamp.CaptureLive(live).StateText;
            int reviewed=StrategicHpRecoveryBound.ComponentHealingUpperBound(parent,player,0,useReviewedSources:true);
            if(!root.UsesPruningComponentHealingCertificate||reviewed!=0)
                throw new InvalidOperationException("Expected reviewed zero-source certificate for deferred listener; rejection="+root.PruningComponentHealingRejection+", bound="+reviewed);
            armed=true;
            using(SimulationNotificationIsolation.Enter())child.Damage(player.Creature,6,ValueProp.Unblockable|ValueProp.Unpowered,null);
            int shadowHp=child.State.GetCreature(player.Creature).CurrentHp;
            if(callbacks!=0||DescribeContinuationContractState(parent,root,player)!=parentBefore
                ||ContinuationStamp.CaptureLive(live).StateText!=liveBefore)
                throw new InvalidOperationException("Shadow invoked deferred observer or changed root/live.");
            await CreatureCmd.Damage(new BlockingPlayerChoiceContext(),player.Creature,6,
                ValueProp.Unblockable|ValueProp.Unpowered,null!);
            for(int i=0;i<8&&!healed;i++)await NGame.Instance.ToSignal(NGame.Instance.GetTree(),Godot.SceneTree.SignalName.ProcessFrame);
            if(!healed||callbacks<1||player.Creature.CurrentHp!=shadowHp+2
                ||DescribeContinuationContractState(parent,root,player)!=parentBefore)
                throw new InvalidOperationException("Deferred HP observer counterexample did not reproduce.");
            var output=new{reviewedBound=reviewed,root.UsesPruningComponentHealingCertificate,root.UsesKnownNativeHealingPolicy,
                callbacks,shadowHp,nativeHp=player.Creature.CurrentHp,unmodeledHeal=2,
                unknownDirectHealthObserver=false,unknownTrackerObserver=true,
                shadowDidNotInvokeLiveObserver=true,frozenParentAfterNativeAdvance=true,productionPrunes=0,searchStarted=false};
            File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/finite-health-capacity-proof-20261008/deferred-audience-details.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
            _completedChecks.Add("TaskCapacity:UnknownDeferredTrackerEvent:ZeroCertificateActualTwoHeal:DirectAudienceUnchanged:ParentIsolation");
            _completedChecks.Add("TASK_DEFERRED_HEALTH_AUDIENCE "+JsonSerializer.Serialize(output));
        }
        finally{CombatManager.Instance.StateTracker.CombatStateChanged-=UnknownDeferredObserver;}
    }

}

