using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Potions;
using MegaCrit.Sts2.Core.Models.Powers;
namespace CombatSolver;
// Research-only primitive allowance. No root/source/callback certificate is inferred.
internal readonly record struct TaskRecoveryCapacityEnvelope(int Healing, int CapacityIncrease)
{
    internal int? OptimisticRecovered(int recovered, int hp, int maxHp)
    {
        if(recovered<0||hp<0||hp>maxHp||Healing<0||CapacityIncrease<0
            ||Healing==int.MaxValue||CapacityIncrease==int.MaxValue)return null;
        long result=(long)recovered+Math.Min((long)Healing,(long)maxHp-hp+CapacityIncrease);
        return result>=int.MaxValue?null:(int)result;
    }
}
internal sealed partial class UnattendedTestRunner
{
    private async Task AssertTaskFiniteHealthCapacityAsync(CombatState live, Player player)
    {
        SetStage("task_finite_health_capacity");
        var rows=new List<object>();int explicitForks=0;
        async Task Check(string label,int maxHp,int hp,string second,int[] order)
        {
            foreach(var power in player.Creature.Powers.OfType<RegenPower>().ToArray())await PowerCmd.Remove(power);
            await CreatureCmd.SetMaxHp(player.Creature,maxHp);await CreatureCmd.SetCurrentHp(player.Creature,hp);
            foreach(var potion in player.PotionSlots.ToArray())potion?.Discard();
            InjectPotionForTest(player,"FRUIT_JUICE");InjectPotionForTest(player,second);
            var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();explicitForks++;
            string Before(CombatPredictionSimulator sim)=>DescribeContinuationContractState(sim,root,player);
            string parentBefore=Before(parent);
            var combat=(SimulatedCombatState)parent.State.CombatState;
            long growth=0;long direct=0;
            foreach(int slot in new[]{0,1})
            {
                PotionModel potion=combat.GetPotionAtSlot(player,slot)!;
                if(potion.GetType()==typeof(FruitJuice))growth+=(long)decimal.Ceiling(Math.Max(0,potion.DynamicVars.MaxHp.BaseValue));
                else if(potion.GetType()!=typeof(BloodPotion))throw new InvalidOperationException("Unknown fixture source.");
            }
            long maxFutureHp=Math.Min(999_999_999L,maxHp+growth);
            foreach(int slot in new[]{0,1})
            {
                PotionModel potion=combat.GetPotionAtSlot(player,slot)!;
                if(potion.GetType()==typeof(BloodPotion))direct+=(long)decimal.Ceiling(maxFutureHp*potion.DynamicVars["HealPercent"].BaseValue/100m);
            }
            var envelope=new TaskRecoveryCapacityEnvelope(checked((int)(growth+direct)),checked((int)growth));
            int optimism=envelope.OptimisticRecovered(0,hp,maxHp)??throw new InvalidOperationException("Finite fixture allowance refused.");
            int legacy=StrategicHpRecoveryBound.OptimisticRecoveredHp(0,hp,maxHp,envelope.Healing);
            var sim=parent.Fork();explicitForks++;
            foreach(int slot in order)
            {
                var branch=(SimulatedCombatState)sim.State.CombatState;var potion=branch.GetPotionAtSlot(player,slot)!;
                string liveBefore=ContinuationStamp.CaptureLive(live).StateText;
                using(SimulationNotificationIsolation.Enter())
                {
                    int start=sim.History.Entries.Count;
                    if(!PotionExecutionSupport.Prepare(sim,branch,potion,slot,player.Creature)
                        ||!PotionExecutionSupport.Complete(sim,branch,potion,player.Creature,null,start,new ForkableSet<uint>())
                        ||!CombatBeamSolver.SettleReplayActionBoundary(sim,branch))throw new InvalidOperationException("Fixture potion suspended.");
                }
                var expected=CaptureSimulated(sim,branch,player,live.Enemies[0]);
                if(Before(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore)
                    throw new InvalidOperationException("Capacity work changed parent or live before native action.");
                var native=player.GetPotionAtSlotIndex(slot)!;
                using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(25));
                GameAction action=await SolverController.EnqueueAndCaptureActionAsync(
                    candidate=>candidate is UsePotionAction use&&ReferenceEquals(use.Player,player)&&use.PotionIndex==(uint)slot,
                    ()=>native.EnqueueManualUse(player.Creature),deadline.Token);
                await action.CompletionTask.WaitAsync(deadline.Token);
                AssertSnapshotEqual(expected,CaptureActual(live,player,live.Enemies[0]),_request.ScenarioId,label+":"+slot);
                if(Before(parent)!=parentBefore)throw new InvalidOperationException("Native advance changed frozen parent.");
            }
            int actualRecovery=sim.State.GetCreature(player.Creature).CurrentHp-hp;
            if(actualRecovery>optimism)throw new InvalidOperationException("Capacity envelope underestimates native recovery.");
            rows.Add(new{label,hp,maxHp,order,envelope.Healing,envelope.CapacityIncrease,optimism,legacy,actualRecovery,
                finalHp=player.Creature.CurrentHp,finalMaxHp=player.Creature.MaxHp,legacyUnderestimates=actualRecovery>legacy});
            _completedChecks.Add("TaskCapacity:"+label+":NativePotionUse:FullStateRng:FrozenParentAfterLiveAdvance");
        }
        await Check("FullHpTwoFruit",75,75,"FRUIT_JUICE",new[]{0,1});
        await Check("FruitThenBlood",75,60,"BLOOD_POTION",new[]{0,1});
        await Check("BloodThenFruit",75,60,"BLOOD_POTION",new[]{1,0});
        await Check("CeilingTwoFruit",999_999_997,999_999_997,"FRUIT_JUICE",new[]{0,1});
        if(new TaskRecoveryCapacityEnvelope(int.MaxValue,0).OptimisticRecovered(0,75,75)!=null
            ||new TaskRecoveryCapacityEnvelope(0,int.MaxValue).OptimisticRecovered(0,75,75)!=null
            ||new TaskRecoveryCapacityEnvelope(5,5).OptimisticRecovered(int.MaxValue-1,75,75)!=null)
            throw new InvalidOperationException("Unknown/overflow allowance should be refused.");
        var parallelRoot=CombatRootSnapshot.Capture(live);var parallelParent=parallelRoot.ForkSimulator();explicitForks++;
        string parallelBefore=DescribeContinuationContractState(parallelParent,parallelRoot,player);
        string liveStable=ContinuationStamp.CaptureLive(live).StateText;
        var children=Enumerable.Range(0,16).Select(_=>parallelParent.Fork()).ToArray();explicitForks+=16;
        await Task.WhenAll(children.Select((child,index)=>Task.Run(()=>{
            int gain=index+1;child.GainMaxHp(player.Creature,gain);
            var state=child.State.GetCreature(player.Creature);
            var bound=new TaskRecoveryCapacityEnvelope(gain,gain).OptimisticRecovered(0,999_999_999,999_999_999);
            if(bound!=gain||state.MaxHp!=999_999_999||state.CurrentHp!=999_999_999)
                throw new InvalidOperationException("Capped branch capacity disagrees.");
        })));
        if(parallelBefore!=DescribeContinuationContractState(parallelParent,parallelRoot,player)
            ||liveStable!=ContinuationStamp.CaptureLive(live).StateText)throw new InvalidOperationException("Parallel capacity work changed parent/live.");
        var output=new{rows,explicitForks,parallelBranches=16,unknownAndOverflowRefused=true,
            wholeSourceCertificate=false,productionPrunes=0,searchStarted=false};
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/finite-health-capacity-proof-20261008/native-details.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
        _completedChecks.Add("TASK_FINITE_HEALTH_CAPACITY "+JsonSerializer.Serialize(output));
    }
}

