                    {
                        int existingCount = combatState.Enemies.Count(candidate =>
                            candidate.IsAlive
                            && candidate.Monster != null
                            && ModelMatches(candidate.Monster, check.MonsterId));
                        while (existingCount <= check.MonsterOccurrence)
                        {
                            await AddMonsterForTestAsync(
