			NCombatRoom.Instance?.GetCreatureNode(_owner)?.ShowHoverTips(new global::<>z__ReadOnlySingleElementList<IHoverTip>(_intent.GetHoverTip(_targets, _owner)));
		}
	}

	private void OnUnhovered()
	{
		NCombatRoom.Instance?.GetCreatureNode(_owner)?.HideHoverTips();
	}

