	private bool TryReadInt(LineEdit edit, int minimum, int maximum, out int value)
	{
		if (int.TryParse(edit.Text.Trim(), out value) && value >= minimum && value <= maximum)
		{
			return true;
		}
		SetStatus(string.Format(L("ritsulib.debugTools.invalidInteger", "Enter an integer between {0} and {1}."), minimum, maximum), error: true);
		return false;
	}

	private static Creature[] CurrentCreatures()
	{
		CombatState obj = CombatManager.Instance.DebugOnlyGetState();
		return ((obj != null) ? (from creature in obj.Creatures.Where(IsVisibleCombatant)
			orderby creature.CombatId
			select creature).ToArray() : null) ?? Array.Empty<Creature>();
	}

	private uint PreferredCreatureCombatId(IReadOnlyList<Creature> creatures)
	{
		uint? selectedCreatureCombatId = _selectedCreatureCombatId;
		if (selectedCreatureCombatId.HasValue)
		{
			uint selected = selectedCreatureCombatId.GetValueOrDefault();
			if (creatures.Any((Creature creature) => creature.CombatId == selected))
			{
				return selected;
			}
		}
		if (TryGetTargetPlayer(out Player target))
		{
			selectedCreatureCombatId = target.Creature.CombatId;
			if (selectedCreatureCombatId.HasValue)
			{
				uint targetCombatId = selectedCreatureCombatId.GetValueOrDefault();
				if (creatures.Any((Creature creature) => creature.CombatId == targetCombatId))
				{
					return targetCombatId;
				}
			}
		}
		return creatures[0].CombatId.Value;
	}

	private static bool HasActiveCombatState(Player player)
	{
		if (CombatManager.Instance.IsInProgress && !CombatManager.Instance.IsOverOrEnding)
		{
			return player.PlayerCombatState != null;
		}
		return false;
	}

