	private static IReadOnlyList<CapabilityDisplayRow> CreateCapabilityDisplayRows(IReadOnlyList<IModelCapability> capabilities)
	{
		List<CapabilityDisplayRow> list = new List<CapabilityDisplayRow>();
		for (int i = 0; i < capabilities.Count; i++)
		{
			IModelCapability capability = capabilities[i];
			string text = SafeCapabilityState(capability);
			if (text == null)
			{
				CapabilityDisplayRow capabilityDisplayRow = list.FirstOrDefault((CapabilityDisplayRow row) => row.StateText == null && row.Capability.GetType() == capability.GetType() && string.Equals(row.Capability.CapabilityId, capability.CapabilityId, StringComparison.Ordinal));
				if (capabilityDisplayRow != null)
				{
					capabilityDisplayRow.Count++;
					continue;
				}
			}
			list.Add(new CapabilityDisplayRow(capability, i, text));
		}
		return list;
	}

	private static string CapabilityDisplayName(IModelCapability capability)
	{
		string text = capability.GetType().Name;
		if (text.EndsWith("Capability", StringComparison.Ordinal) && text.Length > "Capability".Length)
		{
			string text2 = text;
			int length = "Capability".Length;
			text = text2.Substring(0, text2.Length - length);
		}
		StringBuilder stringBuilder = new StringBuilder(text.Length + 8);
		for (int i = 0; i < text.Length; i++)
		{
			char c = text[i];
			if (i > 0 && char.IsUpper(c) && (!char.IsUpper(text[i - 1]) || (i + 1 < text.Length && char.IsLower(text[i + 1]))))
			{
				stringBuilder.Append(' ');
			}
			stringBuilder.Append(c);
		}
		return stringBuilder.ToString();
	}

