	private static IReadOnlyList<IModelCapability> SafeGetCapabilities(AbstractModel model)
	{
		try
		{
			if (ModelCapabilities.TryGet(model, out ModelCapabilitySet collection))
			{
				return collection.All;
			}
			IReadOnlyList<IModelCapability> result;
			if (!ModelCapabilityDefaults.HasDefaultCapabilitySource(model))
			{
				IReadOnlyList<IModelCapability> readOnlyList = Array.Empty<IModelCapability>();
				result = readOnlyList;
			}
			else
			{
				result = ModelCapabilities.Get(model).All;
			}
			return result;
		}
		catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
		{
			RitsuLibFramework.Logger.Warn($"[DebugToolsUi] Could not inspect capabilities for '{model.Id}': {ex.Message}", 1);
			return Array.Empty<IModelCapability>();
		}
	}

	private static string? SafeCapabilityState(IModelCapability capability)
	{
		if (!(capability is IModelCapabilityJsonState modelCapabilityJsonState))
		{
			return null;
		}
		try
		{
			JsonNode jsonNode = modelCapabilityJsonState.SaveState();
			if (jsonNode == null)
			{
				return null;
			}
			string text = jsonNode.ToJsonString(new JsonSerializerOptions
			{
				WriteIndented = false
			});
			if (text.Length > 180)
			{
				text = text.Substring(0, 180) + "…";
			}
			return string.Format(L("ritsulib.debugTools.capabilities.stateInline", "Schema {0} · {1}"), modelCapabilityJsonState.SchemaVersion, text);
		}
		catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
		{
			RitsuLibFramework.Logger.Warn("[DebugToolsUi] Could not serialize capability '" + capability.CapabilityId + "': " + ex.Message, 1);
			return L("ritsulib.debugTools.capabilities.stateUnavailable", "State preview unavailable");
		}
	}

	private static int GetCapabilityStateHash(AbstractModel? model)
	{
		if (model == null)
		{
			return 0;
		}
		HashCode hashCode = default(HashCode);
		foreach (IModelCapability item in SafeGetCapabilities(model))
		{
			hashCode.Add<string>(item.CapabilityId, StringComparer.Ordinal);
			hashCode.Add(item.GetType());
			if (item is IModelCapabilityJsonState modelCapabilityJsonState)
			{
				try
				{
					hashCode.Add(modelCapabilityJsonState.SchemaVersion);
					hashCode.Add<string>(modelCapabilityJsonState.SaveState()?.ToJsonString(), StringComparer.Ordinal);
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					hashCode.Add(ex.GetType());
				}
			}
		}
		return hashCode.ToHashCode();
	}

