		{
			ShowActionWarning(feedback.GetLocalizedText());
			return;
		}
		_selectedCreaturePresetId = preset.Id;
		SetStatus(L("ritsulib.debugTools.creaturePresets.savedStatus", "Creature preset saved."), error: false);
		ScheduleRefresh();
	}

	private void UpdateCreaturePreset(RitsuDebugCreaturePreset current, Creature creature)
	{
		if (!RitsuDebugCreaturePresetStore.TryCapture(creature, current.Name, out RitsuDebugCreaturePreset preset, out RitsuDebugActionFeedback feedback))
		{
			ShowActionWarning(feedback.GetLocalizedText());
			return;
		}
		preset.Id = current.Id;
		if (!RitsuDebugCreaturePresetStore.TrySave(preset, out feedback))
		{
			ShowActionWarning(feedback.GetLocalizedText());
			return;
		}
		_selectedCreaturePresetId = preset.Id;
		SetStatus(L("ritsulib.debugTools.creaturePresets.updatedStatus", "Creature preset updated."), error: false);
		ScheduleRefresh();
	}

