		{
			_pileCardPollElapsed = 0.0;
			return;
		}
		_pileCardPollElapsed += delta;
		if (_pileCardPollElapsed < 0.35)
		{
			return;
		}
		_pileCardPollElapsed = 0.0;
		PileCardEntry[] pileCardEntries = GetPileCardEntries(target);
		int pileCardSnapshotHash = GetPileCardSnapshotHash(pileCardEntries);
		if (_pileCardSnapshotHash != pileCardSnapshotHash)
		{
			_pileCardSnapshotHash = pileCardSnapshotHash;
			if (_currentBrowser is RitsuDebugCardCatalog ritsuDebugCardCatalog)
			{
				ritsuDebugCardCatalog.UpdateEntries(CreatePileCardCatalogEntries(pileCardEntries));
			}
			else
			{
				RebuildBrowser();
			}
		}
	}

