		}
		catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
		{
			RitsuLibFramework.Logger.Warn($"[DebugToolsUi] Action submission failed: {ex}", 1);
			string text = L("ritsulib.debugTools.requestFailed", "The requested change could not be submitted. See the game log for details.");
			SetStatus(text, error: true);
			RitsuToastService.ShowError(text, L("ritsulib.debugTools.toastTitle", "Developer tools"), (Action)null);
			return false;
		}
	}

